{"content":"{
  "main_characters": [
    {
      "name": "陈宇",
      "role": "protagonist",
      "identity": "火星基地宇航员，植物学家",
      "traits": ["坚韧", "孤独", "温柔", "执着", "理性"],
      "overt_motivation": "在火星生存下去，种出足够的土豆",
      "covert_motivation": "寻找与地球、与妻子的连接",
      "secret_fear": "害怕自己已经疯了，害怕妻子真的已经不在了",
      "misperception_of_other": "最初认为妻子是幻觉或幽灵",
      "hidden_connection": "与妻子通过时间线错位重新相遇"
    },
    {
      "name": "林晨",
      "role": "deuteragonist",
      "identity": "地球科学家，通过时间线错位来到火星",
      "traits": ["聪慧", "勇敢", "温柔", "坚定", "神秘"],
      "overt_motivation": "告诉丈夫\"我在你身后\"，陪伴他",
      "covert_motivation": "跨越时间线，重新与丈夫相爱",
      "secret_fear": "害怕时间线会修正，自己会消失",
      "misperception_of_other": "担心丈夫无法接受时间线错位的真相",
      "hidden_connection": "通过摩斯密码和氧气消耗异常引导丈夫发现自己"
    }
  ],
  "supporting_characters": [
    {
      "name": "MOSS",
      "function": "助力",
      "identity": "火星基地AI系统",
      "description": "理性、幽默，帮助主角解谜氧气消耗异常和时间线错位的原因，提供情感支持"
    }
  ],
  "relationship_dynamics": "陈宇与林晨是夫妻关系，因地球毁灭和时间线错位而分离。林晨通过时间线错位来到火星，与陈宇重新相遇。两人在封闭的太空站中重新相爱，共同面对生存挑战和时间线修正的威胁。MOSS作为AI助手，帮助他们解谜和稳定时间线。"
}
","path":"characters.json"}

{"content":"{
  "act_one": {
    "description": "建立火星生存世界观，引入主角陈宇的孤独日常，通过三年前的信号和氧气消耗异常，引出妻子林晨的\"复得\"，建立核心冲突：时间线错位的谜团和夫妻重逢的温情。",
    "key_chapters": [
      {
        "chapter_number": 1,
        "chapter_title": "土豆与孤独",
        "core_event": "陈宇在火星基地种土豆的日常，展现孤独的生存状态和对地球的思念。",
        "emotional_tone": "孤独、坚韧、淡淡的忧伤",
        "key_scenes": [
          "陈宇在温室里检查土豆生长情况",
          "与MOSS的日常对话，展现孤独感",
          "回忆地球和妻子的片段"
        ]
      },
      {
        "chapter_number": 2,
        "chapter_title": "三年前的信号",
        "core_event": "陈宇收到三年前的地球信号，发现是妻子林晨在地球毁灭前发给他的告别讯息。",
        "emotional_tone": "震惊、悲伤、怀念",
        "key_scenes": [
          "信号接收器突然响起，收到三年前的信号",
          "观看妻子的告别视频，情绪崩溃",
          "MOSS提醒信号中有摩斯密码附加信息"
        ]
      },
      {
        "chapter_number": 3,
        "chapter_title": "我在你身后",
        "core_event": "陈宇破解摩斯密码\"我在你身后\"，发现氧气消耗异常，回头看到妻子林晨。",
        "emotional_tone": "震惊、疑惑、温情",
        "key_scenes": [
          "破解摩斯密码，回头却空无一人",
          "MOSS报告氧气消耗数据显示舱内多一个人",
          "林晨突然出现，解释时间线错位"
        ]
      }
    ],
    "turning_point": "妻子林晨真的出现了，不是幻觉，而是通过时间线错位来到火星。"
  },
  "act_two": {
    "description": "夫妻在火星重新相爱，种田日常的温情与解谜过程交织。时间线开始不稳定，妻子偶尔消失，氧气危机加剧，主角必须做出选择：接受失去还是抗争到底。",
    "key_chapters": [
      {
        "chapter_number": 4,
        "chapter_title": "火星田园",
        "core_event": "陈宇与林晨在火星重新相爱，一起种土豆，享受封闭太空站的温情时光。",
        "emotional_tone": "甜蜜、温馨、治愈",
        "key_scenes": [
          "两人一起在温室种土豆，回忆地球时光",
          "林晨帮助陈宇改进种植方案",
          "夜晚一起看火星的星空，重新确认彼此的爱"
        ]
      },
      {
        "chapter_number": 5,
        "chapter_title": "时间线的裂缝",
        "core_event": "陈宇和林晨在MOSS的帮助下，解谜氧气消耗异常和时间线错位的原因。",
        "emotional_tone": "好奇、紧张、温情",
        "key_scenes": [
          "MOSS分析氧气消耗数据，发现时间线异常",
          "林晨解释自己如何通过时间线错位来到火星",
          "两人讨论时间线修正的可能性"
        ]
      },
      {
        "chapter_number": 6,
        "chapter_title": "消失的瞬间",
        "core_event": "时间线开始不稳定，林晨偶尔消失，陈宇陷入恐慌和挣扎。",
        "emotional_tone": "恐惧、焦虑、不舍",
        "key_scenes": [
          "林晨突然消失几分钟，陈宇崩溃",
          "林晨重新出现，解释时间线修正力",
          "两人决定一起寻找稳定时间线的方法"
        ]
      },
      {
        "chapter_number": 7,
        "chapter_title": "氧气危机",
        "core_event": "氧气系统出现故障，陈宇和林晨必须做出选择：谁牺牲自己修复系统。",
        "emotional_tone": "紧张、牺牲、爱",
        "key_scenes": [
          "氧气系统故障，警报响起",
          "两人争着去修复系统，都愿意为对方牺牲",
          "MOSS提出第三种方案：利用时间线能量修复系统"
        ]
      }
    ],
    "turning_point": "发现时间线修正的方法，但需要付出代价：林晨可能需要回到原来的时间线。"
  },
  "act_three": {
    "description": "高潮对决：与时间线修正力抗争，找到稳定时间线的方法。HE结局：妻子留下，两人在火星建立新生活，种土豆+相爱。",
    "key_chapters": [
      {
        "chapter_number": 8,
        "chapter_title": "时间之战",
        "core_event": "陈宇和林晨与时间线修正力抗争，利用MOSS的计算和两人的爱，找到稳定时间线的方法。",
        "emotional_tone": "紧张、坚定、爱",
        "key_scenes": [
          "时间线修正力加强，林晨面临消失的危险",
          "陈宇拒绝放弃，与时间线修正力抗争",
          "MOSS计算出稳定时间线的方法：利用火星的特殊能量场"
        ]
      },
      {
        "chapter_number": 9,
        "chapter_title": "新的开始",
        "core_event": "成功稳定时间线，林晨留下，两人在火星建立新生活。",
        "emotional_tone": "喜悦、希望、甜蜜",
        "key_scenes": [
          "时间线稳定，林晨不再消失",
          "两人庆祝，重新确认彼此的爱",
          "开始规划火星基地的未来"
        ]
      },
      {
        "chapter_number": 10,
        "chapter_title": "火星家园",
        "core_event": "HE结局：陈宇和林晨在火星建立新生活，种土豆、相爱，MOSS成为他们的家人。",
        "emotional_tone": "温馨、甜蜜、希望",
        "key_scenes": [
          "土豆丰收，两人庆祝",
          "林晨怀孕（可选），象征新生命的希望",
          "三人（陈宇、林晨、MOSS）在火星看地球升起，展望未来"
        ]
      }
    ]
  }
}
","path":"outline.json"}

